import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, vec3, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const group = new Group();

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // Convert hex to normalized RGB for TSL nodes
  const hexToRgb = (hex) => {
    const r = parseInt(hex.slice(1, 3), 16) / 255;
    const g = parseInt(hex.slice(3, 5), 16) / 255;
    const b = parseInt(hex.slice(5, 7), 16) / 255;
    return vec3(r, g, b);
  };

  const inkColor = hexToRgb(colors.ink);
  const surfaceColor = hexToRgb(colors.surface);

  // 1. STAGE: Build a backdrop plane to defeat the FLAT_VOID defect.
  // Center is offset to stay fixed at (0,0) in screen coordinates when parent is placed at (-3.2, -0.3, 0)
  const backdropGeo = new PlaneGeometry(7.5, 6.5);
  const backdropMaterial = new MeshBasicNodeMaterial({ depthWrite: false });

  // Create an engineered gradient surface with a subtle scanline pattern as "grain"
  const scanline = uv().y.mul(250.0).sin().mul(0.015).add(1.0);
  backdropMaterial.colorNode = mix(surfaceColor, inkColor, uv().y).mul(scanline);

  const backdropMesh = new Mesh(backdropGeo, backdropMaterial);
  backdropMesh.position.set(3.2, 0.3, -2.5);
  group.add(backdropMesh);

  // 2. SPRITE: Billboarded textured plane formatted to atlas aspect ratio (512:320 -> 1.6)
  const spriteWidth = 2.4;
  const spriteHeight = 1.5;
  const spriteGeo = new PlaneGeometry(spriteWidth, spriteHeight);
  const spriteMaterial = new MeshBasicNodeMaterial({ transparent: true });

  const spriteMesh = new Mesh(spriteGeo, spriteMaterial);
  spriteMesh.position.set(0, 0, 0);
  group.add(spriteMesh);

  // Billboarding behavior targeting the active camera
  spriteMesh.onBeforeRender = (renderer, scene, camera) => {
    spriteMesh.quaternion.copy(camera.quaternion);
  };

  // Load the floating accent assets safely
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      spriteMaterial.colorNode = texture(tex);
      spriteMaterial.needsUpdate = true;
    });
  }

  // 3. MOTION: Elegant rise-in and settle introduction
  const tl = gsap.timeline();
  spriteMesh.position.y = -0.4;
  spriteMesh.scale.set(0.9, 0.9, 0.9);

  tl.to(spriteMesh.position, {
    y: 0,
    duration: 0.9,
    ease: 'power3.out'
  });

  tl.to(spriteMesh.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 1.1,
    ease: 'power4.out'
  }, '<');

  // Apply cinematic primitives if present
  const primitivesCleanup = [];
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((primitive) => {
      if (ctx.primitives[primitive.name]) {
        const prim = ctx.primitives[primitive.name](group, primitive.params);
        if (prim && prim.cleanup) {
          primitivesCleanup.push(prim.cleanup);
        }
      }
    });
  }

  // Cleanup handler
  group.userData = {
    cleanup() {
      tl.kill();
      primitivesCleanup.forEach((clean) => clean());
      backdropGeo.dispose();
      backdropMaterial.dispose();
      spriteGeo.dispose();
      spriteMaterial.dispose();
    }
  };

  return group;
}
